const b = msg.payload || {};
msg.params = [
    String(b.email || ''),
    String(b.password || ''),
    String(b.name || '')
];
return msg;

const row = (msg.payload && msg.payload[0]) || {};
if (row.token) {
    msg.statusCode = 200;
    msg.payload = { token: row.token, user_id: row.user_id, name: row.name };
    return msg;
}
// email_taken vira 409; o resto e erro de validacao
const err = row.error || 'invalid';
msg.statusCode = (err === 'email_taken') ? 409 : 400;
msg.payload = { error: err };
return msg;
